<section class="pb-5"><div class="container"><form class="filter-bar mb-4" method="get"><div class="row g-2"><div class="col-lg-5"><input class="form-control" name="q" value="<?=h($q)?>" placeholder="Search places, food, experiences..."></div><div class="col-6 col-lg-3"><select class="form-select" name="category"><option value="">All categories</option><?php foreach(['Nature','Wildlife','Culture','Food','Adventure','Religious','Photography','Family','Shopping','Local Experiences'] as $c):?><option <?=$category===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></div><div class="col-6 col-lg-2"><select class="form-select"><option>Any budget</option><option>Under NPR 1,000</option><option>NPR 1,000–3,000</option></select></div><div class="col-lg-2"><button class="btn btn-brand w-100">Search</button></div></div></form>
<div class="d-flex gap-2 flex-wrap mb-4"><?php foreach(['Nature','Wildlife','Culture','Food','Adventure','Religious','Photography','Family'] as $c): ?><a class="chip <?=$category===$c?'active':''?>" href="explore.php?category=<?=urlencode($c)?>"><?=$c?></a><?php endforeach; ?></div>
